          "Weight of Water",
          "Lighthouse",
          "Mara",
          "Jonah",
          "/dev",
          "sample-vault",
          ".fountain",
          // What a tutorial writes in practice, if one ran before this check.
          "Practice Play",
          "SOREL",
          "beastly",
